// api/fantasytimes/ingest-deepdive.js
// ─────────────────────────────────────────────────────────────────────────────
// Vera reporter intake endpoint.
//
// Vera is the only FantasyTimes reporter whose content is NOT generated by a
// Vercel cron endpoint. Vera's full deepdive markdown + structured knowledge
// extraction records are produced externally by the Forge Research Agent
// (Codex CLI on a Hostinger VPS) and posted to this endpoint manually via
// scripts/ingest-vera.js.
//
// This endpoint:
//   1. Authenticates the caller via VERA_INGEST_SECRET (Bearer).
//   2. Validates the request (fullMarkdown, extractedRecords, topicSlug).
//   3. Calls Claude Sonnet (claude-sonnet-4-6) with VERA_SUMMARY_SYSTEM_PROMPT
//      and forces tool use against PUBLISH_DEEPDIVE_SUMMARY_TOOL to produce
//      a 1,000-1,500 char Vera-voiced editorial summary.
//   4. Writes the full markdown + records to fantasyTimesDeepdives.
//   5. Writes the summary to fantasyTimesStories with type 'deepdive', linked
//      back to the deepdive doc via visualConfig.fullDeepdiveId.
//   6. Both writes happen atomically in a single Firestore batch — no orphan
//      possible.
//
// Phase 1: the story doc lands in Firestore with status 'published' but
// feed.js/agentTriggerGate.js/agent/decide.js filter type==='deepdive' so it
// does not surface in the UI or agent context until Phase 2 ships the
// deepdive card layout.
// ─────────────────────────────────────────────────────────────────────────────

import { getGenerationConfig } from '../_utils/wireGenerationConfig.js';
import { wireModelCall } from '../_utils/wireModelCall.js';
import { applySecurityMiddleware } from '../_utils/security.js';
import { getFirebaseAdmin } from '../_utils/firebaseAdmin.js';
import {
  REPORTER_PROFILES,
  VERA_SUMMARY_SYSTEM_PROMPT,
  PUBLISH_DEEPDIVE_SUMMARY_TOOL,
} from '../_utils/fantasyTimesPrompts.js';

export const config = { maxDuration: 60 };

const LOG_PREFIX = '[FantasyTimes:Vera:Ingest]';

function logInfo(msg, data = null) {
  const ts = new Date().toISOString();
  console.log(`${ts} ${LOG_PREFIX} ${msg}`, data ? JSON.stringify(data) : '');
}

function logError(msg, data = null) {
  const ts = new Date().toISOString();
  console.error(`${ts} ${LOG_PREFIX} ${msg}`, data ? JSON.stringify(data) : '');
}

function countWords(text) {
  if (!text || typeof text !== 'string') return 0;
  return text.trim().split(/\s+/).filter(Boolean).length;
}

/**
 * Derive unique tickers from the extractedRecords array. Records emitted by
 * the Forge Agent are not strictly typed — we look for the common shapes:
 *   { type: 'company', ticker: 'VRT', ... }
 *   { symbol: 'VRT', ... }
 *   { ticker: 'VRT', ... }
 * Returns a deduped uppercase array. Empty if nothing usable found.
 */
function deriveTickersFromRecords(records) {
  if (!Array.isArray(records)) return [];
  const set = new Set();
  for (const r of records) {
    if (!r || typeof r !== 'object') continue;
    const candidate = r.ticker || r.symbol;
    if (typeof candidate === 'string' && candidate.trim()) {
      set.add(candidate.trim().toUpperCase());
    }
  }
  return Array.from(set);
}

/**
 * Derive unique theme tags from extractedRecords. Looks for records with
 * type 'theme' or a top-level `theme` field.
 */
function deriveThemesFromRecords(records) {
  if (!Array.isArray(records)) return [];
  const set = new Set();
  for (const r of records) {
    if (!r || typeof r !== 'object') continue;
    const candidate = r.theme || (r.type === 'theme' ? r.name : null);
    if (typeof candidate === 'string' && candidate.trim()) {
      set.add(candidate.trim());
    }
  }
  return Array.from(set);
}

export default async function handler(req, res) {
  if (applySecurityMiddleware(req, res, { rateLimit: { limit: 5, windowMs: 60000 } })) {
    return;
  }

  // --- Auth: Bearer token only. No cron path; this endpoint is manual-only. ---
  const expected = process.env.VERA_INGEST_SECRET;
  if (!expected) {
    logError('VERA_INGEST_SECRET not configured');
    return res.status(500).json({ ok: false, error: 'Ingest secret not configured' });
  }
  const authHeader = req.headers.authorization || '';
  if (authHeader !== `Bearer ${expected}`) {
    return res.status(401).json({ ok: false, error: 'Unauthorized' });
  }

  if (req.method !== 'POST') {
    return res.status(405).json({ ok: false, error: 'Method not allowed' });
  }

  if (!process.env.CLAUDE_API_KEY) {
    return res.status(500).json({ ok: false, error: 'AI service not configured' });
  }

  // --- Validate request body ---
  const body = req.body || {};
  const {
    fullMarkdown,
    extractedRecords,
    sourceFile,
    topicSlug,
    primaryTicker,
    tickers: providedTickers,
    sector: providedSector,
  } = body;

  if (typeof fullMarkdown !== 'string' || fullMarkdown.trim().length === 0) {
    return res.status(400).json({ ok: false, error: 'fullMarkdown is required and must be a non-empty string' });
  }
  if (!Array.isArray(extractedRecords)) {
    return res.status(400).json({ ok: false, error: 'extractedRecords is required and must be an array' });
  }
  if (extractedRecords.some((r) => r === null || typeof r !== 'object' || Array.isArray(r))) {
    return res.status(400).json({ ok: false, error: 'extractedRecords entries must each be an object' });
  }
  if (typeof topicSlug !== 'string' || topicSlug.trim().length === 0) {
    return res.status(400).json({ ok: false, error: 'topicSlug is required and must be a non-empty string' });
  }

  const slug = topicSlug.trim();
  logInfo('Ingest received', {
    topicSlug: slug,
    markdownChars: fullMarkdown.length,
    recordCount: extractedRecords.length,
    sourceFile: sourceFile || null,
  });

  try {
    const db = getFirebaseAdmin();

    // --- Generate Vera-voiced summary via Sonnet, forced tool use ---
    // Params (incl. the Sonnet latency pins) from the frozen execution
    // object; wireModelCall is the sole transport (P11 / R4-B2).
    const executionConfig = getGenerationConfig('vera_deepdive');
    logInfo('Calling Sonnet for summary', {
      model: executionConfig.model,
      topicSlug: slug,
    });

    const { response } = await wireModelCall(executionConfig, {
      system: VERA_SUMMARY_SYSTEM_PROMPT,
      tools: [PUBLISH_DEEPDIVE_SUMMARY_TOOL],
      tool_choice: { type: 'tool', name: 'publish_deepdive_summary' },
      messages: [{ role: 'user', content: fullMarkdown }],
    });

    const toolBlock = response.content.find((b) => b.type === 'tool_use');
    if (!toolBlock || !toolBlock.input) {
      logError('Sonnet returned no tool_use block', { topicSlug: slug });
      return res.status(500).json({ ok: false, error: 'AI did not return structured summary' });
    }

    const summary = toolBlock.input;

    // Defensive sanity checks — the tool schema covers structure, but the
    // size constraints in the prompt are advisory; clamp/validate here.
    const headline = String(summary.headline || '').slice(0, 120).trim();
    const subheadline = String(summary.subheadline || '').slice(0, 200).trim();
    const summaryBody = String(summary.body || '').trim();
    if (!headline || !subheadline || !summaryBody) {
      logError('Sonnet summary missing required fields', { topicSlug: slug });
      return res.status(500).json({ ok: false, error: 'AI summary missing required fields' });
    }

    // --- Derive metadata from extractedRecords as fallbacks ---
    const derivedTickers = deriveTickersFromRecords(extractedRecords);
    const derivedThemes = deriveThemesFromRecords(extractedRecords);

    const finalTickers = Array.isArray(providedTickers) && providedTickers.length > 0
      ? providedTickers.map((t) => String(t).toUpperCase())
      : derivedTickers;

    // Themes come from Sonnet but back-fill with derived themes if AI returned nothing.
    const finalThemes = Array.isArray(summary.themes) && summary.themes.length > 0
      ? summary.themes
      : derivedThemes;

    const finalTopSectors = Array.isArray(summary.topSectors) ? summary.topSectors.slice(0, 3) : [];
    const finalPrimaryTicker = primaryTicker
      ? String(primaryTicker).toUpperCase()
      : (finalTickers[0] || null);
    const finalSector = providedSector || finalTopSectors[0] || null;

    // --- Pre-allocate refs so we can cross-link before writing ---
    const deepdiveRef = db.collection('fantasyTimesDeepdives').doc();
    const storyRef = db.collection('fantasyTimesStories').doc();
    const deepdiveId = deepdiveRef.id;
    const storyId = storyRef.id;

    const now = new Date();
    const expiresAt = new Date(now.getTime() + REPORTER_PROFILES.vera.expiryHours * 60 * 60 * 1000);

    // Computed once and mirrored onto BOTH docs in the atomic batch below. The story
    // doc copy lets the front-page FeaturedDeepdiveBand / VeraMobilePreview render a
    // read-time without fetching the separate (large) deepdive doc.
    const wordCount = countWords(fullMarkdown);

    const deepdiveDoc = {
      storyId,
      fullMarkdown,
      extractedRecords,
      sourceFile: sourceFile || null,
      topicSlug: slug,
      generatedAt: now,
      wordCount,
    };

    const storyDoc = {
      reporter: 'vera',
      reporterName: REPORTER_PROFILES.vera.name,
      reporterBeat: REPORTER_PROFILES.vera.beat,
      type: 'deepdive',
      generatedBy: 'forge-agent',
      headline,
      subheadline,
      body: summaryBody,
      wordCount, // mirrored from deepdiveDoc so the front-page band/card show read-time
      tickers: finalTickers,
      primaryTicker: finalPrimaryTicker,
      sector: finalSector,
      themes: finalThemes,
      sentiment: summary.sentiment || 'neutral',
      urgency: 'low',
      recommended_action: summary.recommended_action || 'RESEARCH',
      dataSnapshot: null,
      newsContext: null,
      visualType: 'deepdive-card',
      visualConfig: {
        fullDeepdiveId: deepdiveId,
        topicSlug: slug,
      },
      publishedAt: now,
      expiresAt,
      status: 'published',
      batchId: null,
    };

    // --- Atomic batch write: both docs land or neither does ---
    const batch = db.batch();
    batch.set(deepdiveRef, deepdiveDoc);
    batch.set(storyRef, storyDoc);
    await batch.commit();

    logInfo('Published Vera deepdive', {
      topicSlug: slug,
      storyId,
      deepdiveId,
      headline,
      bodyChars: summaryBody.length,
    });

    return res.status(200).json({
      ok: true,
      storyId,
      deepdiveId,
      summary: {
        headline,
        subheadline,
        bodyPreview: summaryBody.slice(0, 200),
      },
    });
  } catch (err) {
    logError('Ingest failed', {
      topicSlug: slug,
      error: err.message,
      stack: err.stack,
    });
    return res.status(500).json({ ok: false, error: 'Deepdive ingest failed' });
  }
}
